# 3.7 — Windows Update trong System log (WindowsUpdateClient 18/19/21/22/27…) — phần "sự kiện" của câu chuyện; log văn bản chi tiết (WindowsUpdate.log, CBS.log…) chỉ có trên máy Windows.
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object nguon -eq 'Microsoft-Windows-WindowsUpdateClient' | Group-Object id | Sort-Object Count -Descending | Select-Object Count,@{n='Id';e={$_.Name}} | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { $_.nguon -eq 'Microsoft-Windows-WindowsUpdateClient' -and $_.id -eq 19 } | Select-Object -Last 3 @{n='UTC';e={$_.t.ToString('yyyy-MM-dd HH:mm')}},may,@{n='Ban cap nhat';e={$_.data.updateTitle.Substring(0,[math]::Min(80,$_.data.updateTitle.Length))}} | Format-Table -AutoSize
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object { $_.nguon -eq 'Microsoft-Windows-WindowsUpdateClient' -and $_.id -in 21,22,27 } | Select-Object -First 4 @{n='UTC';e={$_.t.ToString('yyyy-MM-dd HH:mm')}},may,id,@{n='Data';e={(($_.data.PSObject.Properties.Value -join ' | ') -replace '\s+',' ').Substring(0,[math]::Min(60,(($_.data.PSObject.Properties.Value -join ' | ') -replace '\s+',' ').Length))}} | Format-Table -AutoSize
